// 1. Access the correct data layer from Evolution API
const body = $json.body;
const data = body.data || body; // Handles both direct and nested data structures
// 2. CORRECT SENDER EXTRACTION (Picks remoteJid instead of instance sender)
const senderRaw = data.key?.remoteJid || "";
const senderPhone = senderRaw.split('@')[0].replace(/\D/g, ''); 
// 3. EXTRACT MESSAGE CONTENT
const messageText = data.message?.conversation || 
                    data.message?.extendedTextMessage?.text || "";
// 4. PRECISION PERCENTAGE EXTRACTION
const percentRegex = /(\d+)(?=\s*%|\s*percent)/i; 
const percentMatch = messageText.match(percentRegex);
const percentage = percentMatch ? percentMatch[1] + "%" : null;
// 5. PRECISION TASK ID EXTRACTION (Tid + Numbers)
const taskIdRegex = /(Tid\d{1,6})/i;
const taskIdMatch = messageText.match(taskIdRegex);
const taskId = taskIdMatch ? taskIdMatch[0].toUpperCase() : null;
return {
  senderPhone,        // e.g. 15550000001
  percentage,         // e.g., "82%"
  taskId,             // e.g., "TID0001"
  Comments: messageText, // The full message for your DB history
  processedAt: new Date().toISOString()
};

// 1. Get the data from the previous nodes
const dbRow = $("Matching rows").first().json;
const whatsappData = $("Extract data from msg").first().json;

// 2. Convert to a pure number (Removing the apostrophe issue)
// If the user sent "18", this converts it to 0.18 which Smartsheet displays as 18%
const cleanPercentage = parseFloat(whatsappData.percentage) / 100;

return {
    sheetId: $env.SHEET_ID_PROJECT_A, // Smartsheet sheet ID (from environment)
    rowId: dbRow.rowId, 
    updates: {
        // Smartsheet expects decimals (0.5) for percentages (50%)
        "Percentage Complete": cleanPercentage, 
        "Comments": whatsappData.Comments || "Updated via WhatsApp"
    }
};

const allTasks = $input.all();
const context = allTasks.find(item => item.json.adminContext)?.json.adminContext;

// 1. --- DATABASE CONTEXT MEMORY ---
// Corrected to find searched_employee from previous interaction records
const dbFetchItem = allTasks.find(item => item.json.searched_employee !== undefined && item.json.searched_employee !== null);
const lastAuditedName = dbFetchItem ? dbFetchItem.json.searched_employee : "";

if (!context) return [{ json: { text: "🤖 *System Online.* Standby for command. Please provide an employee name to generate an audit." } }];

// 2. --- ROBUST FALLBACK: Handling Invalid/Empty Searches ---
// If the Message Analyzer found only noise, send your requested simple instruction
if (context.intent === "invalid_search") {
    return [{ 
        json: { 
            text: "🔍 *I'm ready to help!* Just write the **Employee Name** (no extra text needed) and I will return all their progress details instantly.",
            remoteJid: context.remoteJid 
        } 
    }];
}

// 3. --- INITIAL AI WELCOME: Dynamic Greetings ---
if (context.intent === "menu") {
    const hour = new Date().getHours();
    let timeGreeting = "Hello";

    if (hour >= 5 && hour < 12) timeGreeting = "Good Morning";
    else if (hour >= 12 && hour < 17) timeGreeting = "Good Afternoon";
    else if (hour >= 17 && hour < 21) timeGreeting = "Good Evening";
    else timeGreeting = "Working late? Hello";

    return [{ 
        json: { 
            text: `${timeGreeting}! I am your *PMO Intelligence Assistant* 🤖\n━━━━━━━━━━━━\nI am currently tracking *${allTasks.length}* total tasks across the organization.\n\n📍 *Quick Start:*\nSimply type any **Employee Name** ony for example "Alex" and I will instantly list exactly what they are doing.\n\n*Example:* "Alex" or "Jordan Lee?"`,
            remoteJid: context.remoteJid 
        } 
    }];
}

// 4. --- PRECISION NAME FILTERING ---
let allIndividualNames = [];
allTasks.forEach(item => {
    const names = (item.json["Assigned To"] || "").split(',').map(n => n.trim()).filter(Boolean);
    allIndividualNames.push(...names);
});

let query = context.searchTerm.toLowerCase().trim();
const matchingUniqueNames = [...new Set(allIndividualNames.filter(name => name.toLowerCase().includes(query)))];
const exactMatch = matchingUniqueNames.find(name => name.toLowerCase() === query);

// Resolve targetName based on current search or context memory
let targetName = exactMatch || (matchingUniqueNames.length === 1 ? matchingUniqueNames[0] : "");

if (context.isCommand || targetName === "") {
    targetName = lastAuditedName; 
}

// 5. --- MULTIPLE MATCHES HANDLING ---
if (matchingUniqueNames.length > 1 && !exactMatch && !context.isCommand) {
    let aiResponse = `🔍 *I found ${matchingUniqueNames.length} profiles matching "${context.searchTerm}":*\n\n`;
    matchingUniqueNames.forEach((name, i) => {
        const count = allIndividualNames.filter(n => n === name).length;
        aiResponse += `*${i + 1}️⃣ ${name}* (${count} Tasks)\n`;
    });
    aiResponse += `\n_Reply with the full name of the individual you wish to audit._`;
    return [{ json: { text: aiResponse, remoteJid: context.remoteJid } }];
}

// 6. --- FINAL VALIDATION: No Name Found ---
// Prevents "undefined" headers by sending a clear simple message
if (!targetName || targetName === "") {
    return [{ 
        json: { 
            text: "❌ *Sorry for the inconvenience.* \n\nKindly just type the **Employee Name** only (e.g., Alex) and I will generate the audit for you.", 
            remoteJid: context.remoteJid 
        } 
    }];
}

// 7. --- PERFORMANCE & ANALYTICS ENGINE ---
const employeeTasks = allTasks.filter(item => {
    const names = (item.json["Assigned To"] || "").split(',').map(n => n.trim());
    return names.includes(targetName);
});

let arrays = { active: [], pending: [], completed: [] };
let metrics = { totalPct: 0, responseCount: 0, lastMsg: "None", lastTime: "N/A" };

employeeTasks.forEach(t => {
    const task = t.json;
    const p = parseInt(task["Percentage Complete"]) || 0;
    metrics.totalPct += p;

    const hasResponse = task["User Response"] && task["User Response"] !== "null" && task["User Response"] !== "N/A";
    if (hasResponse) metrics.responseCount++;

    const startDate = (task["Start"] || "TBD").toString().split('T')[0];
    const finishDate = (task["Finish"] || "TBD").toString().split('T')[0];
    const duration = task["Duration"] || "N/A";

    const taskDetail = `🔹 *${task["Task Name"]}*\n` +
                       `   ┣ 📊 *${p}% Complete* | ⏳ *${duration}*\n` +
                       `   ┗ 📅 ${startDate} ➔ ${finishDate}`;

    if (p === 100) arrays.completed.push(taskDetail);
    else if (p === 0) arrays.pending.push(taskDetail);
    else arrays.active.push(taskDetail);

    if (task["User Response Time"] && task["User Response Time"] !== "N/A") {
        metrics.lastTime = task["User Response Time"];
        metrics.lastMsg = task["User Response"];
    }
});

const total = employeeTasks.length;
const avg = total > 0 ? (metrics.totalPct / total).toFixed(1) : 0;
const efficiency = avg > 80 ? "⭐ Elite" : avg > 40 ? "📈 Stable" : "⚠️ Critical";

// 8. --- RESPONSE BRANCHING ---
let report = "";
const nextSteps = `━━━━━━━━━━━━━━━━━━━━\n🔍 *Detailed Insight Needed?*\n\nType **Active**, **Completed**, or **Pending** for ${targetName.split(' ')[0]}.\n\n*Audit someone else?* Just provide their name and I'll share a detailed report of that employee.`;

if (context.filter === "active") {
    report = `🚀 *All the Active tasks displayed below for employee ${targetName}.*\n` +
             `━━━━━━━━━━━━━━━━━━━━\n` +
             `📍 *Total active tasks are (${arrays.active.length})*\n\n` + 
             (arrays.active.join('\n\n') || "No active tasks in progress.") + `\n\n${nextSteps}`;
} else if (context.filter === "completed") {
    report = `✅ *All the Completed tasks displayed below for employee ${targetName}.*\n` +
             `━━━━━━━━━━━━━━━━━━━━\n` +
             `📍 *Total completed tasks are (${arrays.completed.length})*\n\n` + 
             (arrays.completed.join('\n\n') || "No completed tasks found.") + `\n\n${nextSteps}`;
} else if (context.filter === "pending") {
    report = `💤 *All the Pending tasks displayed below for employee ${targetName}.*\n` +
             `━━━━━━━━━━━━━━━━━━━━\n` +
             `📍 *Total pending tasks are (${arrays.pending.length})*\n\n` + 
             (arrays.pending.join('\n\n') || "No pending tasks found.") + `\n\n${nextSteps}`;
} else {
    report = `📊 *EXECUTIVE AUDIT: ${targetName.toUpperCase()}*\n`;
    report += `━━━━━━━━━━━━━━━━━━━━\n`;
    report += `🏆 *Rating:* ${efficiency}\n`;
    report += `📈 *Avg. Completion:* ${avg}%\n\n`;
    report += `✅ *Finished:* ${arrays.completed.length} / ${total}\n`;
    report += `⏳ *Active:* ${arrays.active.length}\n`;
    report += `💤 *Not Started:* ${arrays.pending.length}\n\n`;
    report += `💬 *Engagement:* ${metrics.responseCount} Total Responses\n`;
    report += `🕒 *Last Feedback:* ${metrics.lastTime}\n`;
    report += `🗨️ *Latest Msg:* "${metrics.lastMsg}"\n\n`;

    if (arrays.active.length > 0) {
        report += `📝 *Top Active Focus (Latest 2):*\n${arrays.active.slice(-2).join('\n\n')}\n`;
    }
    report += `\n${nextSteps}`;
}

return [{ json: { text: report, remoteJid: context.remoteJid, targetName: targetName } }];

const body = $input.item.json.body;
const data = body?.data;
const rawMsg = (data?.message?.conversation || data?.message?.extendedTextMessage?.text || "").trim();

// 1. Clean characters but PRESERVE the apostrophe for step 6
const adminMsg = rawMsg.toLowerCase().replace(/[?.,!@#$%&()\-=_+]/g, "").trim();
const remoteJid = data?.key?.remoteJid || $env.ADMIN_WHATSAPP_JID || "";

let filter = "summary";
let isCommand = false;

// 2. Intent Detection
const activeKeywords = ["active", "progress", "doing", "current", "working"];
const completedKeywords = ["completed", "done", "finished", "history", "did", "achieved"];
const pendingKeywords = ["pending", "todo", "backlog", "remaining", "left", "stuck"];

if (activeKeywords.some(kw => adminMsg.includes(kw))) filter = "active";
else if (completedKeywords.some(kw => adminMsg.includes(kw))) filter = "completed";
else if (pendingKeywords.some(kw => adminMsg.includes(kw))) filter = "pending";

// 3. Command Detection
const quickCmds = ["active", "progress", "completed", "done", "pending", "backlog", "todo"];
if (quickCmds.includes(adminMsg)) isCommand = true;

// 4. Greeting Detection
const isGreeting = /^(hi|hello|hey|heya|hola|salam|asalam|morning|afternoon|evening|help|menu|start|what's up|whats\s?up|yo|hlo|guyz|admin|assistant|pmo|bot|get\s?started)/i.test(adminMsg);

// 5. Conversational Noise
const conversationalNoise = /\b(what|whats|is|any|task|tasks|did|do|of|for|check|show|audit|report|tell|let|me|the|current|about|everything|all|summary|list|info|status|progress|pending|completed|active|done|doing|working|on|please|can|could|you|provide|details|asking|give|fetch|get|look|up|at|searching|find|view|display|stats|metrics|performance|logs|records|updates|current|situation|update|position|where|is|how|many|are|left|stuck|finished|history|logs|auditing|monitoring|track|tracking|workload|assigned|to|individual|person|employee|member|user|profile|know|insight|overview|briefing|data|brief|review|agenda|item|items|action|activities|activity|daily|weekly|monthly|record|file|files|details|document|documentation|database|db|sheet|spreadsheet|table|row|entry|entries|assigned|responsibility|responsibilities|role|job|work|working|worked|project|projects|pmo|system|bot|assistant|hello|hi|hey|good|morning|evening|afternoon|salam|please|kindly|just|simply|actually|basically|specifically|want|need|looking|requesting|demand|require|query|search|identify|reveal|extract|pull|scan|read|analyze)\b/g;

// 6. IMPROVED Name Extraction: Handles 's, 't, 're, etc.
let searchTerm = (isCommand || isGreeting) ? "" : adminMsg
    .replace(conversationalNoise, " ")  
    .replace(/'\w+/g, "")                // NEW: Removes apostrophe AND any letters following it (e.g., 's, 't, 're)
    .replace(/'/g, "")                   // Final cleanup for lone apostrophes
    .replace(/\s+/g, " ")
    .trim();

// 7. Final Intent Routing
let finalIntent = isGreeting ? "menu" : (searchTerm === "" && !isCommand) ? "invalid_search" : "employee_search";

return [{
    json: {
        adminContext: {
            intent: finalIntent,
            searchTerm: searchTerm || "",
            filter,
            remoteJid,
            isCommand
        }
    }
}];
